actionJson:
{
  "id": "20spo-roledef-001-add",
  "brandColor": "#007ee5",
  "icon": "https://conn-afd-prod-endpoint-bmc9bqahasf3grgk.b01.azurefd.net/v1.0.1769/1.0.1769.4352/sharepointonline/icon.png",
  "isTrigger": false,
  "operationName": "roledefinition-add",
  "operationDefinition": {
    "type": "OpenApiConnection",
    "inputs": {
      "host": {
        "connectionName": "shared_sharepointonline",
        "operationId": "HttpRequest",
        "apiId": "/providers/Microsoft.PowerApps/apis/shared_sharepointonline"
      },
      "parameters": {
        "dataset": "{{SITE_URL}}",
        "parameters/method": "POST",
        "parameters/uri": "_api/web/roledefinitions",
        "parameters/headers": {
          "Accept": "application/json;odata=nometadata",
          "Content-Type": "application/json;charset=utf-8"
        },
        "parameters/body": "{\"BasePermissions\": {\"High\": \"{{PERMISSIONS_HIGH}}\", \"Low\": \"{{PERMISSIONS_LOW}}\"}, \"Description\": \"{{DESCRIPTION}}\", \"Name\": \"{{ROLE_NAME}}\"}"
      },
      "authentication": {
        "type": "Raw",
        "value": "@json(decodeBase64(triggerOutputs().headers['X-MS-APIM-Tokens']))['$ConnectionKey']"
      }
    },
    "runAfter": {},
    "description": "Creates a custom permission level. High/Low are the two 32-bit halves of the SP.BasePermissions bitmask; easiest is to clone an existing role definition's values and adjust.",
    "metadata": {
      "operationMetadataId": "a1b2c3d4-0072-4000-8000-000000000001"
    }
  }
}

